use ark_bn254::{Fq as Aq,Fr as Ar};use ark_ff::{BigInteger,Field,PrimeField};use num_bigint::{BigInt as Z,Sign};use zopro_bn254::{FpConfig,FqConfig,FrConfig,ifma8::Ifma8};
fn z(n:u64)->Z{Z::from(n)}fn words(w:[u64;4])->Z{Z::from_bytes_le(Sign::Plus,&w.into_iter().flat_map(u64::to_le_bytes).collect::<Vec<_>>())}fn w(x:&Z)->[u64;4]{let(s,v)=x.to_u64_digits();assert_ne!(s,Sign::Minus);assert!(v.len()<=4);let mut out=[0;4];out[..v.len()].copy_from_slice(&v);out}fn md(x:Z,p:&Z)->Z{let r=x%p;if r<z(0){r+p}else{r}}fn af<A:PrimeField>(x:&Z)->A{let(s,b)=x.to_bytes_le();let a=A::from_le_bytes_mod_order(&b);if s==Sign::Minus{-a}else{a}}fn ai<A:PrimeField>(x:A)->Z{Z::from_bytes_le(Sign::Plus,&x.into_bigint().to_bytes_le())}fn next(s:&mut u64)->u64{*s^=*s<<13;*s^=*s>>7;*s^=*s<<17;*s}fn rnd(s:&mut u64,p:&Z)->Z{words(std::array::from_fn(|_|next(s)))%p}
fn check<C:FpConfig,A:PrimeField,const M:bool>() -> usize{let p=words(C::P);assert_eq!(p,Z::from_bytes_le(Sign::Plus,&A::MODULUS.to_bytes_le()));let two=&p*z(2);let bits=if M{256}else{260};let rf=A::from(2u64).pow([bits]).inverse().unwrap();let ef=if M{A::ONE}else{A::from(16u64).inverse().unwrap()};let mut edge=vec![z(0),z(1),&p-z(1),p.clone(),&p+z(1),&two-z(1),two.clone()];for bit in[26,51,52,53,64,103,104,127,155,156,191,207,208,251,253]{let x=z(1)<<bit;for d in[-1i64,0,1]{let a=&x+Z::from(d);if a>=z(0)&&a<two{edge.push(a);}}}edge.sort();edge.dedup();let n=edge.len();let mut rng=0x746f702d63726f73;let mut count=0;let mut chain: [[Z;8];4]=std::array::from_fn(|_|std::array::from_fn(|_|rnd(&mut rng,&two)));
 let rows=n*n+2048+1024;for row in 0..rows{let input:[[Z;8];4]=if row<n*n{std::array::from_fn(|j|std::array::from_fn(|i|match j{0=>edge[(row/n+i)%n].clone(),1=>edge[(row%n+3*i)%n].clone(),2=>edge[(row/n+5*i+7)%n].clone(),_=>edge[(row%n+7*i+11)%n].clone()}))}else if row<n*n+2048{std::array::from_fn(|_|std::array::from_fn(|_|rnd(&mut rng,&two)))}else{chain.clone()};for a in &input{assert!(a.iter().all(|x|*x>=z(0)&&*x<=two));}let a:[Ifma8<C,M>;4]=std::array::from_fn(|j|unsafe{Ifma8::top_cross_from_raw(&input[j].each_ref().map(|x|w(x)))});let out=[tested_mul(&a[0],&a[1]),tested_sum(&a[0],&a[1],&a[2],&a[3]),tested_diff(&a[0],&a[1],&a[2],&a[3])];let original=[a[0].mul(&a[1]),a[0].sum2(&a[1],&a[2],&a[3]),a[0].difference2(&a[1],&a[2],&a[3])];let mut returned=vec![];
 for(mode,result)in out.iter().enumerate(){let digits=result.top_cross_raw_digits();assert_eq!(digits,original[mode].top_cross_raw_digits());let packed=result.get();let mut rawstate: [Z;8]=std::array::from_fn(|_|z(0));for i in 0..8{assert!(digits.iter().all(|v|v[i]<(1<<52)));let value:Z=digits.iter().enumerate().map(|(j,v)|Z::from(v[i])<<(52*j)).sum();assert!(value>=z(0)&&value<two);let[a,b,c,d]=input.each_ref().map(|v|v[i].clone());let expected=(af::<A>(&a)*af::<A>(&b)+match mode{0=>A::ZERO,1=>af::<A>(&c)*af::<A>(&d),_=>-af::<A>(&c)*af::<A>(&d)})*rf;assert_eq!(md(value.clone(),&p),ai(expected));assert_eq!(md((&a*&b+if mode==0{z(0)}else if mode==1{&c*&d}else{-&c*&d})*ai(rf),&p),ai(expected));let host=words(packed[i].0);assert!(host<p);assert_eq!(af::<A>(&host),expected*ef);rawstate[i]=value;count+=1;}returned.push(rawstate);}
 if row>=n*n+2048{chain.rotate_left(1);chain[3]=returned[row%3].clone();}else if row==n*n+2047{for j in 0..4{chain[j]=input[j].clone();}}
 }println!("NATIVE_FIELD prime={} radix={bits} edges={n} rows={rows} raw_outputs={count} exports={count}",if C::P==FqConfig::P{"Fq"}else{"Fr"});count}
#[test]fn all_fields_radices_loose_operations_and_chains(){let n=check::<FqConfig,Aq,true>()+check::<FqConfig,Aq,false>()+check::<FrConfig,Ar,true>()+check::<FrConfig,Ar,false>();println!("NATIVE_FIELD_TOTAL outputs={n} exports={n}");}

#[inline(never)]fn tested_mul<C:FpConfig,const M:bool>(a:&Ifma8<C,M>,b:&Ifma8<C,M>)->Ifma8<C,M>{a.top_cross_mul(b)}
#[inline(never)]fn tested_sum<C:FpConfig,const M:bool>(a:&Ifma8<C,M>,b:&Ifma8<C,M>,c:&Ifma8<C,M>,d:&Ifma8<C,M>)->Ifma8<C,M>{a.top_cross_sum2(b,c,d)}
#[inline(never)]fn tested_diff<C:FpConfig,const M:bool>(a:&Ifma8<C,M>,b:&Ifma8<C,M>,c:&Ifma8<C,M>,d:&Ifma8<C,M>)->Ifma8<C,M>{a.top_cross_difference2(b,c,d)}
